import org.apache.logging.log4j.Logger;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.InvalidPathException;
import java.nio.file.Path;
import java.nio.file.Paths;

/**
 * 文件存储服务实现，通过 HTTP 与远端文件服务交互，支持上传、下载、删除和存在性检查
 */
@Service
public class FileStorageServiceImpl implements IFileStorage {

    private static final Logger log = LogManager.getLogger(FileStorageServiceImpl.class);

    private static final String FILE_URL_PATTERN = "/file/v1/%s/%s";
    private static final String EXIST_URL_PATTERN = "/file/v1/%s/%s/exist";

    @Autowired
    private ICse cse;

    @Override
    public void uploadFile(String localFilePath, String remoteUrl) {
        validatePathNotBlank(localFilePath, "localPath");
        validatePathNotBlank(remoteUrl, "remotePath");
        S3Path s3Path = parseS3Url(remoteUrl);
        File file = Path.of(localFilePath).toFile();
        String url = buildFileUrl(s3Path);

        HttpEntity fileEntity = MultipartEntityBuilder.create()
                .addBinaryBody("file", file, ContentType.DEFAULT_BINARY, file.getName())
                .build();
        HttpPost httpPost = new HttpPost(url);
        httpPost.setEntity(fileEntity);

        try {
            HttpUtil.getHttpClient().execute(httpPost, response -> {
                if (response.getCode() == 200) {
                    log.info("upload {} success", remoteUrl);
                } else {
                    dealFileHttpError("upload", s3Path, response);
                }
                return null;
            });
        } catch (IOException e) {
            log.error("upload {} failed", s3Path, e);
        }
    }

    @Override
    public void downloadFile(String localFilePath, String remoteUrl) {
        validatePathNotBlank(localFilePath, "localPath");
        validatePathNotBlank(remoteUrl, "remotePath");
        S3Path s3Path = parseS3Url(remoteUrl);
        String url = buildFileUrl(s3Path);

        try {
            HttpUtil.getHttpClient().execute(new HttpGet(url), response -> {
                int status = response.getCode();
                HttpEntity entity = response.getEntity();
                if (status == 200 && entity != null) {
                    try (FileOutputStream out = new FileOutputStream(localFilePath)) {
                        entity.writeTo(out);
                    }
                } else {
                    dealFileHttpError("download", s3Path, response);
                    EntityUtils.consume(response.getEntity());
                }
                return null;
            });
        } catch (IOException e) {
            log.error("download {} failed", s3Path, e);
        }
    }

    @Override
    public void deleteFile(String remoteUrl) {
        validatePathNotBlank(remoteUrl, "path");
        S3Path s3Path = parseS3Url(remoteUrl);
        String url = buildFileUrl(s3Path);

        try {
            HttpUtil.getHttpClient().execute(new HttpDelete(url), response -> {
                if (response.getCode() == 200) {
                    log.info("delete {} success", remoteUrl);
                } else {
                    dealFileHttpError("delete", s3Path, response);
                }
                return null;
            });
        } catch (IOException e) {
            log.error("delete {} failed", s3Path, e);
        }
    }

    @Override
    public boolean exist(String remoteUrl) {
        validatePathNotBlank(remoteUrl, "path");
        S3Path s3Path = parseS3Url(remoteUrl);
        String url = buildExistUrl(s3Path);
        boolean result = false;
        try {
            result = HttpUtil.getHttpClient().execute(new HttpGet(url), response -> {
                if (response.getCode() == 200) {
                    return true;
                }
                if (response.getCode() != 404) {
                    dealFileHttpError("exist", s3Path, response);
                }
                return false;
            });
        } catch (IOException e) {
            log.error("exist {} failed", s3Path, e);
        }
        return result;
    }

    /** 构建文件操作 URL */
    private String buildFileUrl(S3Path s3Path) {
        return "http://" + cse.getReportEndpoint()
                + String.format(FILE_URL_PATTERN, s3Path.getBucket(), s3Path.getName());
    }

    /** 构建文件存在性检查 URL */
    private String buildExistUrl(S3Path s3Path) {
        return "http://" + cse.getReportEndpoint()
                + String.format(EXIST_URL_PATTERN, s3Path.getBucket(), s3Path.getName());
    }

    /**
     * 校验路径非空
     */
    private static void validatePathNotBlank(String path, String paramName) {
        if (StrUtil.isBlank(path)) {
            throw new IllegalArgumentException(paramName + " must not be blank");
        }
    }

    /**
     * 将远端路径解析为 S3Path（bucket + 扁平化文件名）。
     * 路径中第一段为 bucket，其余部分用 "_" 拼接为文件名。
     */
    private static S3Path parseS3Url(String url) {
        if (StrUtil.isBlank(url)) {
            throw new IllegalArgumentException("remotePath must not be blank");
        }
        Path path;
        try {
            path = Paths.get(url);
        } catch (InvalidPathException e) {
            throw new IllegalArgumentException("remotePath is invalid: " + url, e);
        }
        if (path.getNameCount() < 2) {
            throw new IllegalArgumentException("remotePath must contain bucket and key: " + url);
        }
        String bucketName = path.getName(0).toString();
        String name = path.subpath(1, path.getNameCount()).toString().replace("\\", "_").replace("/", "_");
        return new S3Path(bucketName, name);
    }

    /** 统一处理文件操作的 HTTP 错误响应 */
    private static void dealFileHttpError(String method, S3Path file, ClassicHttpResponse response) {
        try {
            HttpEntity entity = response.getEntity();
            if (entity != null) {
                String body = EntityUtils.toString(entity, StandardCharsets.UTF_8);
                BaseResponse badResponse = JSONUtil.toBean(body, BaseResponse.class);
                log.error("{} failed, file:{}, code:{}, msg:{}", method, file,
                        badResponse.getCode(), badResponse.getMessage());
            } else {
                log.error("{} failed, file:{}, code:{}", method, file, response.getCode());
            }
        } catch (Exception e) {
            log.error("{} failed, file:{}, http status:{}", method, file, response.getCode(), e);
        }
    }

    /** S3 路径值对象，包含 bucket 名称和文件名 */
    @Data
    private static class S3Path {
        private final String bucket;
        private final String name;

        @Override
        public String toString() {
            return bucket + "/" + name;
        }
    }
}

package com.huawei.browsergateway.util;

import cn.hutool.core.lang.TypeReference;
import cn.hutool.core.util.StrUtil;
import cn.hutool.json.JSONUtil;
import lombok.Getter;
import org.apache.hc.client5.http.classic.methods.ClassicHttpRequests;
import org.apache.hc.client5.http.classic.methods.HttpUriRequest;
import org.apache.hc.client5.http.impl.classic.CloseableHttpClient;
import org.apache.hc.client5.http.impl.classic.HttpClients;
import org.apache.hc.client5.http.impl.io.PoolingHttpClientConnectionManager;
import org.apache.hc.core5.http.HttpEntity;
import org.apache.hc.core5.http.io.entity.EntityUtils;
import org.apache.hc.core5.http.io.entity.StringEntity;
import org.apache.hc.core5.util.TimeValue;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

import java.io.IOException;

/** HTTP 请求工具类，内部使用连接池复用连接 */
public final class HttpUtil {

    private static final Logger log = LogManager.getLogger(HttpUtil.class);

    @Getter
    private static final CloseableHttpClient httpClient;

    static {
        PoolingHttpClientConnectionManager cm = new PoolingHttpClientConnectionManager();
        cm.setMaxTotal(100);          // 连接池最大总连接数
        cm.setDefaultMaxPerRoute(20); // 每个路由最大连接数
        httpClient = HttpClients.custom()
                .setConnectionManager(cm)
                .evictIdleConnections(TimeValue.ofMinutes(1)) // 自动清理空闲连接
                .build();
    }

    private HttpUtil() {}

    /**
     * 发送 HTTP 请求，忽略响应体
     *
     * @param url    请求地址
     * @param method HTTP 方法（GET/POST 等）
     * @param body   请求体，为空时不设置
     */
    public static void request(String url, String method, String body) {
        execute(url, method, body, response -> {
            if (response.getCode() != 200) {
                log.warn("request for {}, got code {}", url, response.getCode());
            }
            return null;
        });
    }

    /**
     * 发送 HTTP 请求并将响应体反序列化为指定类型
     *
     * @param url           请求地址
     * @param method        HTTP 方法
     * @param body          请求体，为空时不设置
     * @param typeReference 响应体目标类型
     * @param <T>           目标类型
     * @return 反序列化后的响应对象，非 200 或响应体为空时返回 null
     */
    public static <T> T request(String url, String method, String body, TypeReference<T> typeReference) {
        return execute(url, method, body, response -> {
            if (response.getCode() != 200) {
                log.warn("request for {}, got code {}", url, response.getCode());
                return null;
            }
            HttpEntity entity = response.getEntity();
            if (entity == null) return null;
            return JSONUtil.toBean(EntityUtils.toString(entity), typeReference, true);
        });
    }

    /** 构建请求并执行，统一处理 IO 异常 */
    private static <T> T execute(String url, String method, String body,
            org.apache.hc.core5.http.io.HttpClientResponseHandler<T> handler) {
        HttpUriRequest req = ClassicHttpRequests.create(method, url);
        if (!StrUtil.isEmpty(body)) {
            req.setEntity(new StringEntity(body));
        }
        try {
            return httpClient.execute(req, handler);
        } catch (IOException e) {
            log.error("request for {} failed", url, e);
            throw new RuntimeException(e);
        }
    }
}

