public void checkBrowsers() {
        Type.HealthCheckResult result = client.browser().healthCheck();
        if (result.isSuccess()) {
            return;
        }
        Set<String> users = chromeSet.getAllUser();
        Set<String> delUsers = new HashSet<>();
        for (String user : users) {
            UserChrome userChrome = chromeSet.get(user);
            String proxyContextId = userChrome.getChromeDriver().getProxyContextId();
            if (result.getErrContexts().contains(proxyContextId)) {
                delUsers.add(user);
            }
        }
        delUsers.forEach(chromeSet::delete);
    }

private void reportChainInfoWithRetry(int maxRetries) {
        for (int remaining = maxRetries; remaining >= 0; remaining--) {
            log.info("start to report chain endpoints");
            if (chromeSet.reportChainEndpoints()) {
                log.info("report chain endpoint success");
                return;
            }
            if (remaining == 0) {
                log.fatal("report chain endpoint failed");
                return;
            }
            log.info("failed to report, will retry");
            try {
                Thread.sleep(RETRY_INTERVAL_MS);
            } catch (InterruptedException e) {
                log.fatal("failed to sleep", e);
                Thread.currentThread().interrupt();
                return;
            }
        }
    }

public void closeExpiredBrowsers() {
        long now = System.nanoTime();
        Set<String> users = chromeSet.getAllUser();
        for (String user : users) {
            long heartbeats = chromeSet.getHeartbeats(user);
            if (now - heartbeats > TIMEOUT_NANOS) {
                chromeSet.delete(user);
            }
        }
    }

