package com.huawei.browsergateway.scheduled;

import cn.hutool.json.JSONUtil;
import com.huawei.browsergateway.config.Config;
import com.huawei.browsergateway.service.IChromeSet;
import com.huawei.browsergateway.service.impl.UserChrome;
import com.huawei.browsergateway.sdk.ClientImpl;
import com.huawei.browsergateway.sdk.DriverClient;
import com.huawei.browsergateway.sdk.Type;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import javax.annotation.PostConstruct;
import javax.annotation.PreDestroy;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

/**
 * 浏览器实例健康检查任务，定期通过 ChromeDriver 健康检查接口识别并清理异常实例
 */
@Component
public class BrowserCheckTask {

    private static final Logger log = LogManager.getLogger(BrowserCheckTask.class);

    @Autowired
    private IChromeSet chromeSet;
    @Autowired
    private Config config;

    /** 检查周期（毫秒），默认 30 分钟 */
    @Value("${browsergw.scheduled.check-browser-period:1800000}")
    private long period;

    private ScheduledExecutorService scheduler;
    private DriverClient client;

    @PostConstruct
    public void init() {
        client = new ClientImpl(config.getChrome().getEndpoint());
        scheduler = Executors.newSingleThreadScheduledExecutor();
        scheduler.scheduleAtFixedRate(this::checkBrowsers, 0, period, TimeUnit.MILLISECONDS);
        log.info("Browser check task initialized, period: {}ms", period);
    }

    /**
     * 执行健康检查：若全部正常则直接返回；否则找出错误上下文对应的用户实例并删除
     */
    public void checkBrowsers() {
        try {
            log.info("begin scheduled task for check browsers status.");
            long start = System.currentTimeMillis();

            Type.HealthCheckResult result = client.browser().healthCheck();
            if (result.isSuccess()) {
                log.info("check browsers success. cost:{}ms", System.currentTimeMillis() - start);
                return;
            }

            Set<String> delUsers = new HashSet<>();
            for (String user : chromeSet.getAllUser()) {
                UserChrome userChrome = chromeSet.get(user);
                if (userChrome != null && result.getErrContexts().contains(userChrome.getChromeDriver().getProxyContextId())) {
                    delUsers.add(user);
                }
            }

            if (!delUsers.isEmpty()) {
                log.info("These user instances have expired:{}, close.", JSONUtil.toJsonStr(delUsers));
                delUsers.forEach(chromeSet::delete);
            }

            log.info("end scheduled task for check browsers status. cost:{}ms", System.currentTimeMillis() - start);
        } catch (Exception e) {
            log.error("check browser task error.", e);
        }
    }

    @PreDestroy
    public void destroy() {
        if (scheduler != null) {
            scheduler.shutdown();
            log.info("Browser check task destroyed.");
        }
    }
}

package com.huawei.browsergateway.scheduled;

import com.huawei.browsergateway.service.IChromeSet;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.event.ContextRefreshedEvent;
import org.springframework.context.event.EventListener;
import org.springframework.stereotype.Service;

/**
 * 服务启动上报器，在 Spring 上下文就绪后将链路端点信息上报到 CSE，
 * 失败时最多重试 5 次，每次间隔 30 秒
 */
@Service
public class ServiceReporter {

    private static final Logger log = LogManager.getLogger(ServiceReporter.class);

    /** 重试间隔（毫秒） */
    private static final long RETRY_INTERVAL_MS = 30_000;

    @Autowired
    private IChromeSet chromeSet;

    /** 监听上下文刷新事件，触发链路端点上报 */
    @EventListener(ContextRefreshedEvent.class)
    public void startReport(ContextRefreshedEvent event) {
        reportChainInfoWithRetry(5);
        log.info("finish report chain endpoints");
    }

    /**
     * 带重试的链路端点上报，使用循环替代递归避免栈溢出风险
     *
     * @param maxRetries 最大重试次数
     */
    private void reportChainInfoWithRetry(int maxRetries) {
        for (int remaining = maxRetries; remaining >= 0; remaining--) {
            log.info("start to report chain endpoints");
            if (chromeSet.reportChainEndpoints()) {
                log.info("report chain endpoint success");
                return;
            }
            if (remaining == 0) {
                log.fatal("report chain endpoint failed");
                return;
            }
            log.info("failed to report, will retry");
            try {
                Thread.sleep(RETRY_INTERVAL_MS);
            } catch (InterruptedException e) {
                log.fatal("failed to sleep", e);
                Thread.currentThread().interrupt();
                return;
            }
        }
    }
}

package com.huawei.browsergateway.scheduled;

import com.huawei.browsergateway.config.Config;
import com.huawei.browsergateway.service.IChromeSet;
import com.huawei.browsergateway.service.IRemote;
import com.huawei.browsergateway.service.impl.UserBind;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import javax.annotation.PostConstruct;
import javax.annotation.PreDestroy;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

/**
 * 浏览器实例超时关闭任务，定期检查所有实例的活跃状态和心跳时间，
 * 对不活跃或心跳超时的实例执行关闭操作
 */
@Component
public class BrowserCloserTask {

    private static final Logger log = LogManager.getLogger(BrowserCloserTask.class);

    @Autowired
    private IRemote remote;
    @Autowired
    private IChromeSet chromeSet;
    @Autowired
    private Config config;

    /** 检查周期（毫秒），默认 10 分钟 */
    @Value("${browsergw.scheduled.close-browser-period:600000}")
    private long period;

    /** 浏览器实例心跳超时阈值（纳秒） */
    @Value("${browsergw.chrome.ttl}")
    private long ttl;

    private ScheduledExecutorService scheduler;

    @PostConstruct
    public void init() {
        scheduler = Executors.newSingleThreadScheduledExecutor();
        scheduler.scheduleAtFixedRate(this::closeBrowser, 0, period, TimeUnit.MILLISECONDS);
        log.info("Browser closer task initialized, period: {}ms, ttl: {}ns", period, ttl);
    }

    /** 遍历所有用户实例，关闭不活跃或心跳超时的实例 */
    public void closeBrowser() {
        log.info("begin scheduled task for monitoring browser instances.");
        List<String> userIds = new ArrayList<>(chromeSet.getAllUser());
        try {
            for (String userId : userIds) {
                try {
                    UserBind ub = remote.getUserBind(userId);
                    if (!isActive(ub) || isExpired(userId)) {
                        log.info("browser {} is expired, close it.", userId);
                        chromeSet.delete(userId);
                    }
                } catch (Exception e) {
                    log.error("failed to close user {} browser", userId, e);
                }
            }
        } catch (Exception e) {
            log.error("monitoring browser instances error!", e);
        }
    }

    /**
     * 判断心跳是否超时
     *
     * @param userId 用户 ID
     * @return true 表示已超时
     */
    private boolean isExpired(String userId) {
        return System.nanoTime() - chromeSet.getHeartbeats(userId) > ttl;
    }

    /**
     * 判断用户绑定是否有效（绑定到本实例且心跳记录存在）
     *
     * @param userBind 用户绑定信息
     * @return true 表示活跃
     */
    private boolean isActive(UserBind userBind) {
        return userBind != null
                && userBind.getBrowserInstance() != null
                && config.getSelfAddr().equals(userBind.getBrowserInstance())
                && userBind.getHeartbeats() != null;
    }

    @PreDestroy
    public void destroy() {
        if (scheduler != null) {
            scheduler.shutdown();
            log.info("Browser closer task destroyed.");
        }
    }
}

